ALTER TABLE accounting_dimension_assignment_events ADD COLUMN source_ref TEXT;
CREATE TABLE accounting_dimension_budget_events (id INTEGER PRIMARY KEY,dimension_id TEXT NOT NULL,member_id TEXT NOT NULL,account_no TEXT NOT NULL REFERENCES accounts(account_no),period TEXT NOT NULL CHECK(period GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]'),amount REAL NOT NULL CHECK(amount>=0),source_ref TEXT NOT NULL,plan_hash TEXT NOT NULL CHECK(length(plan_hash)=64),event_type TEXT NOT NULL CHECK(event_type IN ('allocated','superseded')),supersedes_budget_id INTEGER REFERENCES accounting_dimension_budget_events(id),idempotency_key TEXT UNIQUE,reason TEXT,actor TEXT NOT NULL,principal TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(dimension_id,member_id,account_no,period,event_type,plan_hash));
CREATE VIEW current_accounting_dimension_budgets AS SELECT e.* FROM accounting_dimension_budget_events e WHERE e.event_type='allocated' AND NOT EXISTS(SELECT 1 FROM accounting_dimension_budget_events s WHERE s.event_type='superseded' AND s.supersedes_budget_id=e.id);
CREATE TRIGGER accounting_dimension_assignment_events_no_update_v32 BEFORE UPDATE ON accounting_dimension_assignment_events BEGIN SELECT RAISE(ABORT,'accounting dimension assignment events are append-only'); END;
CREATE TRIGGER accounting_dimension_assignment_events_no_delete_v32 BEFORE DELETE ON accounting_dimension_assignment_events BEGIN SELECT RAISE(ABORT,'accounting dimension assignment events are append-only'); END;
CREATE TRIGGER accounting_dimension_budget_events_no_update BEFORE UPDATE ON accounting_dimension_budget_events BEGIN SELECT RAISE(ABORT,'accounting dimension budget events are append-only'); END;
CREATE TRIGGER accounting_dimension_budget_events_no_delete BEFORE DELETE ON accounting_dimension_budget_events BEGIN SELECT RAISE(ABORT,'accounting dimension budget events are append-only'); END;
